parameters.pythonCode:
messages = []

for item in _items:
    message = item["json"]

    subject = message.get("subject", "")

    # Ignore FlowCheck's own automatic emails
    if subject.startswith("FlowCheck - Daily Well-being Summary"):
        continue

    if message.get("sentDateTime"):
        messages.append(message)


# No sent emails found
if len(messages) == 0:
    return [
        {
            "json": {
                "sent_emails_today": 0,
                "first_sent_email_utc": None,
                "last_sent_email_utc": None
            }
        }
    ]


# Sort by sent time
messages.sort(key=lambda message: message["sentDateTime"])

first_email = messages[0]["sentDateTime"]
last_email = messages[-1]["sentDateTime"]


return [
    {
        "json": {
            "sent_emails_today": len(messages),
            "first_sent_email_utc": first_email,
            "last_sent_email_utc": last_email
        }
    }
]

